package org.millenaire.common.utilities;public class MillLog{public static class MillenaireException extends Exception{public MillenaireException(String s){super(s);}}public static void minor(Object o,String s){}public static void major(Object o,String s){}public static void error(Object o,String s){throw new AssertionError(s);}public static void printException(Exception e){throw new AssertionError(e);}}